get_ipython().run_cell_magic('manim', 'Taxes', '\nclass Taxes(GraphScene):\n    CONFIG = {\n        "x_axis_label": "$Q_d$",\n        "y_axis_label": "$P$",\n        "x_min": 0,\n        "x_max": 100,\n        "y_min": 0,\n        "y_max": 10,\n        "x_axis_width": FRAME_HEIGHT,\n        "y_axis_height":FRAME_HEIGHT / 2,\n        "x_labeled_nums": [],\n        "y_labeled_nums": [],\n        "y_tick_frequency": 10,\n        "x_tick_frequency": 100,\n        "graph_origin": np.array((-FRAME_X_RADIUS + 1.8*LARGE_BUFF, -FRAME_Y_RADIUS + 2*LARGE_BUFF, 0)),\n        "demand_color": BLUE,\n        "supply_color": ORANGE,\n        "expenditure_color": GREEN,\n        "cs_color": PINK,\n        "ps_color": YELLOW,\n        "surplus_color": BLUE,\n        "pq_color": RED,\n        "axes_color": GREY,\n        "dwl_color": GREY,\n        "gov_color": RED,\n    }\n\n    def construct(self):\n        self.intro_sequence()\n        self.wait(3)\n        self.initialize_eq()\n        self.wait(3)\n        self.tax_eq(2,0)\n        self.wait(3)\n        self.tax_eq(4,0)\n        self.wait(3)\n        self.tax_eq(0,4)\n        self.wait(3)\n        self.tax_eq(4,0)\n        self.wait(3)\n        self.tax_eq(0,4)\n        self.wait(3)\n        self.tax_eq(0,2)\n        self.wait(3)\n        self.tax_eq(0,2)\n        self.tax_wedge(2)\n        self.welfare(2)\n        self.wait(3)\n        self.update_surplus(4)\n        self.wait(3)\n        self.update_surplus(6)\n        self.wait(2)\n        #self.update_surplus(8)\n        #self.wait(2)\n        self.update_surplus(2)\n        self.wait(2)\n        self.incidence(2,1,1)\n        self.wait(3)\n        self.incidence(4,1,1)\n        self.wait(3)\n        self.incidence(4,1,1.5)\n        self.wait(3)\n        self.incidence(4,1.1,1.3)\n        self.wait(3)\n        self.incidence(4,1.1,1)\n        self.wait(3)\n        self.incidence(4,1.4,1)\n        self.wait(3)\n        self.incidence(4,1,1)\n        self.wait(3)\n        self.incidence(4,1,0.8)\n        self.wait(3)\n        self.incidence(4,0.7,1)\n        self.wait(3)\n        self.incidence(2,1,1)\n        self.wait(3)\n        self.summary()\n        \n    def DemandQ(self, priceD):\n        return 100 - 10*priceD\n    \n    def DemandP(self,quantityD):\n        return (10 - quantityD/10)\n    \n    def SupplyQ(self, priceS):\n        return 10*priceS - 20\n    \n    def SupplyP(self,quantityS):\n        return 2 + quantityS /10\n                \n    def intro_sequence(self):\n        title = TextMobject("Tutorial 3.5 | Taxes and Welfare").scale(1.5)\n        self.play(FadeIn(title))\n        self.wait(1)\n        transform_title = TextMobject("Tutorial 3.5 | Taxes and Welfare").scale(1.2)\n        transform_title.to_corner(UP)\n        self.play(\n            Transform(title, transform_title))\n        self.wait(3)\n        self.setup_axes(animate=True)\n        \n    def initialize_eq(self):\n        self.DemandCurveEq = self.get_graph(self.DemandP, self.demand_color, x_min=0, x_max=100)\n        self.DemandCurve = self.get_graph(self.DemandP, self.demand_color, x_min=0, x_max=100)\n        self.SupplyCurveEq = self.get_graph(self.SupplyP, self.supply_color, x_min=0, x_max=80)\n        self.SupplyCurve = self.get_graph(self.SupplyP, self.supply_color, x_min=0, x_max=80)\n        \n        eqp1 = self.coords_to_point(0, 6)\n        eqp2 = self.coords_to_point(40, 6)\n        eqp3 = self.coords_to_point(40, 0)\n        \n        self.horzLineEq = DashedVMobject(Line(eqp1,eqp2, color=self.axes_color))        \n        self.vertLineEq = DashedVMobject(Line(eqp2,eqp3, color=self.axes_color))\n\n        self.vertLine = DashedVMobject(Line(eqp2,eqp3, color=self.axes_color))\n        self.quantDesc = TextMobject(str(40)).scale(0.7)\n        self.quantDesc.add_updater(lambda d: d.next_to(self.vertLine, DOWN))\n        \n        self.horzLineS =  DashedVMobject(Line(eqp1,eqp2, color=self.axes_color))\n        self.priceS = TextMobject("$p_S=$ "+str(6)).scale(0.7)\n        self.priceS.add_updater(lambda d: d.next_to(self.horzLineS, LEFT+DOWN))\n        \n        self.horzLineB =  DashedVMobject(Line(eqp1,eqp2, color=self.axes_color))\n        self.priceB = TextMobject("$p_B=$ "+str(6)).scale(0.7)\n        self.priceB.add_updater(lambda d: d.next_to(self.horzLineB, LEFT+UP))\n        \n        wp = self.coords_to_point(-3, 6)\n        self.taxWedgeS = Line(wp,wp, color=self.axes_color)\n        self.taxWedgeSL = TextMobject("Wedge").scale(0.7)\n        self.taxWedgeSL.next_to(self.taxWedgeS,LEFT)\n        self.taxWedgeB = Line(wp,wp, color=self.axes_color)\n        self.taxWedgeBL = TextMobject("Wedge").scale(0.7)\n        self.taxWedgeBL.next_to(self.taxWedgeB,LEFT)\n        \n        qL = self.coords_to_point(0, -2)\n        qU = self.coords_to_point(6, -2)\n        \n        self.quantityExchanged = Line(qL,qU, color=self.axes_color)\n        self.quantityExchLabel = TextMobject("Quantity Exchanged").scale(0.6)\n        self.quantityExchLabel.add_updater(lambda d: d.next_to(self.quantityExchanged,DOWN))\n        \n        # WELFARE\n        \n        a = self.coords_to_point(135, 10)\n        b = self.coords_to_point(135, 8.5)\n        self.csL = Line(a,b, color=self.cs_color)\n        \n        self.csD = TextMobject("CS")\n        self.csD.next_to(self.csL,LEFT)\n        self.csD.set_color(self.cs_color)\n        \n        a = self.coords_to_point(135, 8)\n        b = self.coords_to_point(135, 6.5)\n        self.psL = Line(a,b, color=self.ps_color)\n        \n        self.psD = TextMobject("PS")\n        self.psD.next_to(self.psL,LEFT)\n        self.psD.set_color(self.ps_color)\n\n        a = self.coords_to_point(135, 6)\n        b = self.coords_to_point(135, 4.5)\n        self.govL = Line(a,b, color=self.gov_color)\n        \n        self.govD = TextMobject("GOV")\n        self.govD.next_to(self.govL,LEFT)\n        self.govD.set_color(self.gov_color)\n        \n        a = self.coords_to_point(135, 4)\n        b = self.coords_to_point(135, 2.5)\n        self.dwlL = Line(a,b, color=self.dwl_color)\n        \n        self.dwlD = TextMobject("DWL")\n        self.dwlD.next_to(self.dwlL,LEFT)\n        self.dwlD.set_color(self.dwl_color)\n\n        \n        self.play(ShowCreation(self.DemandCurveEq))\n        self.play(ShowCreation(self.SupplyCurveEq))\n        self.play(ShowCreation(self.horzLineEq))\n        self.play(ShowCreation(self.vertLineEq))\n        \n        \n    def tax_eq(self, taxS, taxB):\n        self.add(self.quantityExchLabel)\n        def DemandQ(priceD):\n            return (10 + taxB)*10 - 10*priceD\n        def DemandP(quantityD):\n            return 10 - quantityD/10 - taxB\n        def SupplyQ(priceS):\n            return 10*priceS - 10*(2+taxS)\n        def SupplyP(quantityS):\n            return 2 + quantityS /10 + taxS\n        \n        DemandCurve = DashedVMobject(self.get_graph(DemandP, self.demand_color, x_min=0, x_max=100))\n        SupplyCurve = DashedVMobject(self.get_graph(SupplyP, self.supply_color, x_min=0, x_max=80))\n        \n        eqQTax = int(40-5*(taxB+taxS))\n        eqPSTax = int(self.SupplyP(eqQTax))\n        eqPBTax = int(self.DemandP(eqQTax))\n        \n        eqpt1 = self.coords_to_point(eqQTax, 0)\n        eqpt2 = self.coords_to_point(eqQTax, eqPSTax)\n        eqpt3 = self.coords_to_point(0, eqPSTax)\n        eqpt4 = self.coords_to_point(eqQTax, eqPBTax)\n        eqpt5 = self.coords_to_point(0, eqPBTax)\n\n        vertLine = DashedVMobject(Line(eqpt1,eqpt4, color=self.pq_color))\n        quantDesc = TextMobject(str(eqQTax)).scale(0.7)\n        quantDesc.next_to(vertLine, DOWN)\n        \n        horzLineS = DashedVMobject(Line(eqpt2,eqpt3, color=self.pq_color))\n        priceS = TextMobject("$p_S=$ "+str(eqPSTax)).scale(0.7)\n        priceS.next_to(horzLineS, LEFT+DOWN)\n        \n        horzLineB = DashedVMobject(Line(eqpt4,eqpt5, color=self.pq_color))\n        priceB = TextMobject("$p_B=$ "+str(eqPBTax)).scale(0.7)\n        priceB.next_to(horzLineB, LEFT+UP)\n        \n        qL = self.coords_to_point(0, -2)\n        qU = self.coords_to_point(eqQTax, -2)\n        quantityExchanged = Line(qL,qU, color=self.axes_color)\n        \n        self.play(Transform(self.SupplyCurve,SupplyCurve), Transform(self.DemandCurve,DemandCurve),\n                Transform(self.quantDesc,quantDesc),\n                Transform(self.vertLine,vertLine), Transform(self.quantityExchanged,quantityExchanged),\n                Transform(self.horzLineS,horzLineS), Transform(self.priceS,priceS),\n                Transform(self.horzLineB,horzLineB), Transform(self.priceB,priceB))\n    \n    def tax_wedge(self, tax):\n        self.play(FadeOut(self.SupplyCurve), FadeOut(self.DemandCurve))\n        self.remove(self.SupplyCurve)\n        self.remove(self.DemandCurve)\n        eqQTax = int(40-5*(tax))\n        eqPSTax = int(self.SupplyP(eqQTax))\n        eqPBTax = int(self.DemandP(eqQTax))\n        \n        twp1 = self.coords_to_point(-3, eqPSTax)\n        twp2 = self.coords_to_point(-3, eqPBTax)\n\n        taxWedgeS = Line(twp1,twp2, color=self.pq_color)\n        taxWedgeSL = TextMobject("TW ="+str(tax)).scale(0.7)\n        taxWedgeSL.next_to(taxWedgeS, LEFT)\n        \n        eqpt1 = self.coords_to_point(eqQTax, 0)\n        eqpt2 = self.coords_to_point(eqQTax, eqPSTax)\n        eqpt3 = self.coords_to_point(0, eqPSTax)\n        eqpt4 = self.coords_to_point(eqQTax, eqPBTax)\n        eqpt5 = self.coords_to_point(0, eqPBTax)\n\n        vertLine = DashedVMobject(Line(eqpt1,eqpt4, color=self.pq_color))\n        quantDesc = TextMobject(str(eqQTax)).scale(0.7)\n        quantDesc.next_to(vertLine, DOWN)\n        \n        horzLineS = DashedVMobject(Line(eqpt2,eqpt3, color=self.pq_color))\n        priceS = TextMobject("$p_S=$ "+str(eqPSTax)).scale(0.7)\n        priceS.next_to(horzLineS, LEFT+DOWN)\n        \n        horzLineB = DashedVMobject(Line(eqpt4,eqpt5, color=self.pq_color))\n        priceB = TextMobject("$p_B=$ "+str(eqPBTax)).scale(0.7)\n        priceB.next_to(horzLineB, LEFT+UP)\n        \n        qL = self.coords_to_point(0, -2)\n        qU = self.coords_to_point(eqQTax, -2)\n        quantityExchanged = Line(qL,qU, color=self.axes_color)\n                \n        self.play(Transform(self.taxWedgeS,taxWedgeS), Transform(self.taxWedgeSL,taxWedgeSL),\n                    Transform(self.quantDesc,quantDesc),\n                    Transform(self.vertLine,vertLine), Transform(self.quantityExchanged,quantityExchanged),\n                    Transform(self.horzLineS,horzLineS), Transform(self.priceS,priceS),\n                    Transform(self.horzLineB,horzLineB), Transform(self.priceB,priceB))\n        \n        \n    def welfare(self, tax):\n        eqQTax = int(40-5*(tax))\n        eqPSTax = int(self.SupplyP(eqQTax))\n        eqPBTax = int(self.DemandP(eqQTax))\n        \n        # CS\n        a = self.coords_to_point(0, 10)\n        b = self.coords_to_point(eqQTax, eqPBTax)\n        c = self.coords_to_point(0, eqPBTax)\n        self.cs = Polygon(a,b,c, fill_opacity = 0.2, fill_color = self.cs_color, color=self.cs_color)\n        self.csN = Polygon(a,b,c, fill_opacity = 0.2, fill_color = self.cs_color, color=self.cs_color)\n        \n        csN = TextMobject(str(int((10-eqPBTax)*eqQTax/2)))\n        csN.next_to(self.csL, RIGHT)\n        csN.set_color(self.cs_color)\n        \n        self.add(self.csL,self.csD)\n        self.play(FadeIn(self.cs),Transform(self.csN,csN))\n        \n        # PS\n        a = self.coords_to_point(0, eqPSTax)\n        b = self.coords_to_point(eqQTax, eqPSTax)\n        c = self.coords_to_point(0, 2)\n        self.ps = Polygon(a,b,c, fill_opacity = 0.2, fill_color = self.ps_color, color=self.ps_color)\n        self.psN = Polygon(a,b,c, fill_opacity = 0.2, fill_color = self.ps_color, color=self.ps_color)\n        \n        psN = TextMobject(str(int((eqPSTax-2)*eqQTax/2)))\n        psN.next_to(self.psL, RIGHT)\n        psN.set_color(self.ps_color)\n        \n        self.add(self.psL,self.psD)\n        self.play(FadeIn(self.ps),Transform(self.psN,psN))   \n                           \n        # GOV\n        a = self.coords_to_point(0,eqPSTax)\n        b = self.coords_to_point(0,eqPBTax)\n        c = self.coords_to_point(eqQTax,eqPBTax)\n        d = self.coords_to_point(eqQTax,eqPSTax)\n        self.gov = Polygon(a,b,c,d, fill_opacity = 0.1, fill_color = self.gov_color, color=self.gov_color)\n        self.govN = Polygon(a,b,c,d, fill_opacity = 0.1, fill_color = self.gov_color, color=self.gov_color)\n\n        govN = TextMobject(str(int(tax*eqQTax)))\n        govN.next_to(self.govL, RIGHT)\n        govN.set_color(self.gov_color)\n\n        self.add(self.govL,self.govD)\n        self.play(FadeIn(self.gov),Transform(self.govN,govN))  \n        \n        # DWL\n        a = self.coords_to_point(eqQTax,eqPBTax)\n        b = self.coords_to_point(40,6)\n        c = self.coords_to_point(eqQTax,eqPSTax)\n        self.dwl = Polygon(a,b,c, fill_opacity = 0.2, fill_color = self.dwl_color, color=self.dwl_color)\n        self.dwlN = Polygon(a,b,c, fill_opacity = 0.2, fill_color = self.dwl_color, color=self.dwl_color)\n        \n        dwlN = TextMobject(str(int((eqPBTax-eqPSTax)*(40-eqQTax)/2)))\n        dwlN.next_to(self.dwlL, RIGHT)\n        dwlN.set_color(self.dwl_color)\n        \n        self.add(self.dwlL,self.dwlD)\n        self.play(FadeIn(self.dwl),Transform(self.dwlN,dwlN))  \n\n        \n    def update_surplus(self,tax):\n        eqQTax = int(40-5*(tax))\n        eqPSTax = int(self.SupplyP(eqQTax))\n        eqPBTax = int(self.DemandP(eqQTax))\n        \n        twp1 = self.coords_to_point(-3, eqPSTax)\n        twp2 = self.coords_to_point(-3, eqPBTax)\n        \n        taxWedgeS = Line(twp1,twp2, color=self.pq_color)\n        taxWedgeSL = TextMobject("TW ="+str(tax)).scale(0.7)\n        taxWedgeSL.next_to(taxWedgeS, LEFT)\n        \n        eqpt1 = self.coords_to_point(eqQTax, 0)\n        eqpt2 = self.coords_to_point(eqQTax, eqPSTax)\n        eqpt3 = self.coords_to_point(0, eqPSTax)\n        eqpt4 = self.coords_to_point(eqQTax, eqPBTax)\n        eqpt5 = self.coords_to_point(0, eqPBTax)\n\n        vertLine = DashedVMobject(Line(eqpt1,eqpt4, color=self.pq_color))\n        quantDesc = TextMobject(str(int(eqQTax))).scale(0.7)\n        quantDesc.next_to(vertLine, DOWN)\n        \n        horzLineS = DashedVMobject(Line(eqpt2,eqpt3, color=self.pq_color))\n        priceS = TextMobject("$p_S=$ "+str(eqPSTax)).scale(0.7)\n        priceS.next_to(horzLineS, LEFT+DOWN)\n        \n        horzLineB = DashedVMobject(Line(eqpt4,eqpt5, color=self.pq_color))\n        priceB = TextMobject("$p_B=$ "+str(eqPBTax)).scale(0.7)\n        priceB.next_to(horzLineB, LEFT+UP)\n        \n        qL = self.coords_to_point(0, -2)\n        qU = self.coords_to_point(eqQTax, -2)\n        quantityExchanged = Line(qL,qU, color=self.axes_color)\n        \n        # CS\n        a = self.coords_to_point(0, 10)\n        b = self.coords_to_point(eqQTax, eqPBTax)\n        c = self.coords_to_point(0, eqPBTax)\n        cs = Polygon(a,b,c, fill_opacity = 0.2, fill_color = self.cs_color, color=self.cs_color)\n        \n        csN = TextMobject(str(int((10-eqPBTax)*eqQTax/2)))\n        csN.next_to(self.csL, RIGHT)\n        csN.set_color(self.cs_color)\n        \n        # PS\n        a = self.coords_to_point(0, eqPSTax)\n        b = self.coords_to_point(eqQTax, eqPSTax)\n        c = self.coords_to_point(0, 2)\n        ps = Polygon(a,b,c, fill_opacity = 0.2, fill_color = self.ps_color, color=self.ps_color)\n        \n        psN = TextMobject(str(int((eqPSTax-2)*eqQTax/2)))\n        psN.next_to(self.psL, RIGHT)\n        psN.set_color(self.ps_color)\n        \n        # GOV\n        a = self.coords_to_point(0,eqPSTax)\n        b = self.coords_to_point(0,eqPBTax)\n        c = self.coords_to_point(eqQTax,eqPBTax)\n        d = self.coords_to_point(eqQTax,eqPSTax)\n        gov = Polygon(a,b,c,d, fill_opacity = 0.1, fill_color = self.gov_color, color=self.gov_color)\n\n        govN = TextMobject(str(int(tax*eqQTax)))\n        govN.next_to(self.govL, RIGHT)\n        govN.set_color(self.gov_color)\n        \n        # DWL\n        a = self.coords_to_point(eqQTax,eqPBTax)\n        b = self.coords_to_point(40,6)\n        c = self.coords_to_point(eqQTax,eqPSTax)\n        dwl = Polygon(a,b,c, fill_opacity = 0.2, fill_color = self.dwl_color, color=self.dwl_color)\n        \n        dwlN = TextMobject(str(int((eqPBTax-eqPSTax)*(40-eqQTax)/2)))\n        dwlN.next_to(self.dwlL, RIGHT)\n        dwlN.set_color(self.dwl_color)\n\n        self.play(Transform(self.vertLine,vertLine), Transform(self.quantityExchanged,quantityExchanged),\n                    Transform(self.quantDesc,quantDesc),\n                    Transform(self.horzLineS,horzLineS), Transform(self.priceS,priceS),\n                    Transform(self.horzLineB,horzLineB), Transform(self.priceB,priceB),\n                    Transform(self.cs,cs),Transform(self.csN,csN),\n                    Transform(self.ps,ps),Transform(self.psN,psN),\n                    Transform(self.gov,gov),Transform(self.govN,govN),\n                    Transform(self.dwl,dwl),Transform(self.dwlN,dwlN),\n                    Transform(self.taxWedgeS,taxWedgeS), Transform(self.taxWedgeSL,taxWedgeSL),\n                    )\n\n        \n    def incidence(self,tax, SSC, DSC):\n        def DemandQ(priceD):\n            return (priceD - 10*DSC)*20/(5*DSC - 3)\n        def DemandP(quantityD):\n            return 10*DSC - (5*DSC - 3)*quantityD/20\n        def SupplyQ(priceS):\n            return (priceS - 2*SSC)*20/(3-SSC)\n        def SupplyP(quantityS):\n            return 2*SSC + (3-SSC)*quantityS/20\n        \n        DemandCurve = self.get_graph(DemandP, self.demand_color, x_min=0, x_max=100)\n        SupplyCurve = self.get_graph(SupplyP, self.supply_color, x_min=0, x_max=80)\n        \n        eqQTax = (-tax+10*DSC-2*SSC)*20/(5*DSC-SSC)\n        eqPSTax = SupplyP(eqQTax)\n        eqPBTax = DemandP(eqQTax)\n        \n        eqpt1 = self.coords_to_point(eqQTax, 0)\n        eqpt2 = self.coords_to_point(eqQTax, eqPSTax)\n        eqpt3 = self.coords_to_point(0, eqPSTax)\n        eqpt4 = self.coords_to_point(eqQTax, eqPBTax)\n        eqpt5 = self.coords_to_point(0, eqPBTax)\n        \n        #taxWedge = Line(eqpt2,eqpt4, color=self.pq_color)\n        #taxWedgeL = TextMobject("Tax ="+str(tax)).scale(0.7)\n        #taxWedgeL.next_to(taxWedge, LEFT)\n\n        vertLine = DashedVMobject(Line(eqpt1,eqpt4, color=self.pq_color))\n        quantDesc = TextMobject(str(round(eqQTax,1))).scale(0.7)\n        quantDesc.next_to(vertLine, DOWN)\n        \n        horzLineS = DashedVMobject(Line(eqpt2,eqpt3, color=self.pq_color))\n        priceS = TextMobject("$p_S=$ "+str(round(eqPSTax,1))).scale(0.7)\n        priceS.next_to(horzLineS, LEFT+DOWN)\n        \n        horzLineB = DashedVMobject(Line(eqpt4,eqpt5, color=self.pq_color))\n        priceB = TextMobject("$p_B=$ "+str(round(eqPBTax,1))).scale(0.7)\n        priceB.next_to(horzLineB, LEFT+UP)\n        \n        qL = self.coords_to_point(0, -2)\n        qU = self.coords_to_point(eqQTax, -2)\n        quantityExchanged = Line(qL,qU, color=self.axes_color)\n        \n        incp = self.coords_to_point(-2, 6)\n        incSp = self.coords_to_point(-2, eqPSTax)\n        incBp = self.coords_to_point(-2, eqPBTax)\n        taxWedgeS = Line(incp,incSp, color=self.supply_color)\n        taxWedgeSL = TextMobject(str(round(6-eqPSTax,1))).scale(0.7)\n        taxWedgeSL.next_to(taxWedgeS, LEFT)\n        taxWedgeB = Line(incp,incBp, color=self.demand_color)\n        taxWedgeBL = TextMobject(str(round(eqPBTax-6,1))).scale(0.7)\n        taxWedgeBL.next_to(taxWedgeB, LEFT)\n        \n        # CS\n        a = self.coords_to_point(0, 10*DSC)\n        b = self.coords_to_point(eqQTax, eqPBTax)\n        c = self.coords_to_point(0, eqPBTax)\n        cs = Polygon(a,b,c, fill_opacity = 0.2, fill_color = self.cs_color, color=self.cs_color)\n        \n        csN = TextMobject(str(int((10*DSC-eqPBTax)*eqQTax/2)))\n        csN.next_to(self.csL, RIGHT)\n        csN.set_color(self.cs_color)\n        \n        # PS\n        a = self.coords_to_point(0, eqPSTax)\n        b = self.coords_to_point(eqQTax, eqPSTax)\n        c = self.coords_to_point(0, 2*SSC)\n        ps = Polygon(a,b,c, fill_opacity = 0.2, fill_color = self.ps_color, color=self.ps_color)\n        \n        psN = TextMobject(str(int((eqPSTax-2*SSC)*eqQTax/2)))\n        psN.next_to(self.psL, RIGHT)\n        psN.set_color(self.ps_color)\n        \n        # GOV\n        a = self.coords_to_point(0,eqPSTax)\n        b = self.coords_to_point(0,eqPBTax)\n        c = self.coords_to_point(eqQTax,eqPBTax)\n        d = self.coords_to_point(eqQTax,eqPSTax)\n        gov = Polygon(a,b,c,d, fill_opacity = 0.1, fill_color = self.gov_color, color=self.gov_color)\n\n        govN = TextMobject(str(int(tax*eqQTax)))\n        govN.next_to(self.govL, RIGHT)\n        govN.set_color(self.gov_color)\n        \n        # DWL\n        a = self.coords_to_point(eqQTax,eqPBTax)\n        b = self.coords_to_point(40,6)\n        c = self.coords_to_point(eqQTax,eqPSTax)\n        dwl = Polygon(a,b,c, fill_opacity = 0.2, fill_color = self.dwl_color, color=self.dwl_color)\n        \n        dwlN = TextMobject(str(int((eqPBTax-eqPSTax)*(40-eqQTax)/2)))\n        dwlN.next_to(self.dwlL, RIGHT)\n        dwlN.set_color(self.dwl_color)\n\n        self.play(\n                    Transform(self.SupplyCurveEq,SupplyCurve),Transform(self.DemandCurveEq,DemandCurve),\n                    Transform(self.quantDesc,quantDesc),\n                    Transform(self.taxWedgeS,taxWedgeS),Transform(self.taxWedgeSL,taxWedgeSL),\n                    Transform(self.taxWedgeB,taxWedgeB),Transform(self.taxWedgeBL,taxWedgeBL),\n                    Transform(self.vertLine,vertLine), Transform(self.quantityExchanged,quantityExchanged),\n                    Transform(self.horzLineS,horzLineS), Transform(self.priceS,priceS),\n                    Transform(self.horzLineB,horzLineB), Transform(self.priceB,priceB),\n                    Transform(self.cs,cs),Transform(self.csN,csN),\n                    Transform(self.ps,ps),Transform(self.psN,psN),\n                    Transform(self.gov,gov),Transform(self.govN,govN),\n                    Transform(self.dwl,dwl),Transform(self.dwlN,dwlN),)\n                    #Transform(self.taxWedge,taxWedge), Transform(self.taxWedgeL,taxWedgeL),\n                    #Transform(self.incB,incB), Transform(self.incBL,incBL),\n                    #Transform(self.incS,incS), Transform(self.incSL,incSL),)\n        \n        \n    def summary(self):\n        SupplyCurve = self.get_graph(self.SupplyP, self.supply_color, x_min=0, x_max=45)\n        self.play(FadeOut(self.psN), FadeOut(self.psL), FadeOut(self.psD),\n                  FadeOut(self.csN), FadeOut(self.csL), FadeOut(self.csD),\n                  FadeOut(self.dwlN), FadeOut(self.dwlL), FadeOut(self.dwlD),\n                  FadeOut(self.govN), FadeOut(self.govL), FadeOut(self.govD))\n        self.play(Transform(self.SupplyCurveEq,SupplyCurve))\n\n        result0 = TextMobject("A tax on buyers or sellers")\n        result0.move_to(self.coords_to_point(65, 10), LEFT)\n        result0a = TextMobject("has the same effect")\n        result0a.move_to(self.coords_to_point(70, 8), LEFT)\n        self.play(FadeIn(result0),FadeIn(result0a))\n        self.wait(2)\n        self.play(FadeOut(result0),FadeOut(result0a))\n        result1 = TextMobject("DWL increases with taxes")\n        result1.move_to(self.coords_to_point(65, 10), LEFT)\n        self.play(FadeIn(result1))\n        self.wait(2)\n        self.play(FadeOut(result1))\n        result2 = TextMobject("Incidence is lower for")\n        result2.move_to(self.coords_to_point(65, 10), LEFT)\n        result2a = TextMobject("1) more elastic supply curves")\n        result2a.move_to(self.coords_to_point(70, 8), LEFT)\n        result2b = TextMobject("2) more elastic demand curves")\n        result2b.move_to(self.coords_to_point(70, 6), LEFT)\n        self.play(FadeIn(result2),FadeIn(result2a),FadeIn(result2b))\n        self.wait(2)\n        self.play(FadeOut(result2),FadeOut(result2a),FadeOut(result2b))\n        \n        reading = TextMobject("More info: Mankiw Ch. 6 + 8")\n        reading.move_to(self.coords_to_point(65, 10), LEFT)\n        self.play(FadeIn(reading))\n')


